PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?neighborCatchment
WHERE {
  GRAPH <hydroturtle/lamah_ce> {
    # Find the catchment with the highest total precipitation between 2012 and 2015
    {
      SELECT ?targetCatchment (SUM(?precValue) AS ?totalPrecip)
      WHERE {
        ?obs a sosa:Observation ;
             sosa:observedProperty hyobs:hasMeanDailyPrecip ;
             sosa:hasFeatureOfInterest ?targetCatchment ;
             sosa:resultTime ?date ;
             sosa:hasResult ?result .
        ?result qudt:numericValue ?precValue .
        FILTER (?date >= "2012-01-01"^^xsd:date && ?date <= "2015-12-31"^^xsd:date)
      }
      GROUP BY ?targetCatchment
      ORDER BY DESC(?totalPrecip)
      LIMIT 1
    }
    # Get the geometry of the target catchment
    ?targetCatchment geo:hasGeometry ?targetGeom .
    ?targetGeom geo:asWKT ?targetWKT .
    # Find other catchments with geometries
    ?neighborCatchment geo:hasGeometry ?neighborGeom .
    ?neighborGeom geo:asWKT ?neighborWKT .
    FILTER (?neighborCatchment != ?targetCatchment)
    # Use geof:sfTouches to find neighbors (assuming geof:sfTouches is available)
    FILTER(geof:sfTouches(?targetWKT, ?neighborWKT))
  }
}

